def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from functools import wraps
    from collections import defaultdict

    def decorator(func):
        cache = defaultdict(lambda: [0, None])  # count, value
        order = []  # list of keys ordered by frequency

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args if not typed else (args, tuple(kwargs.items()))
            if key in cache:
                cache[key][0] += 1
            else:
                if len(cache) >= maxsize:
                    if maxsize == 0:
                        return func(*args, **kwargs)
                    # Find and remove the least frequently used item
                    lfu_key = min(cache, key=lambda k: cache[k][0])
                    cache.pop(lfu_key)
                    order.remove(lfu_key)
                cache[key] = [1, func(*args, **kwargs)]
                order.append(key)

            return cache[key][1]

        def cache_clear():
            cache.clear()
            order.clear()

        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

